1	// Build config for arm B. Part of the harness (verify.sh gate 0 checks it is untouched).
2	import path from 'node:path';
3	import { defineConfig } from 'vite';
4	
5	const root = path.resolve(import.meta.dirname, '..');
6	
7	export default defineConfig({
8	  root,
9	  publicDir: path.join(root, 'public'),
10	  build: {
11	    outDir: path.join(root, 'dist'),
12	    emptyOutDir: true,
13	    target: 'es2022',
14	    // One nonce'd module script, no preload hints: exactly what a strict CSP with 'strict-dynamic' expects.
15	    modulePreload: false,
16	    sourcemap: false,
17	    rollupOptions: { output: { inlineDynamicImports: true } },
18	  },
19	  plugins: [harnessGuard()],
20	});
21	
22	/**
23	 * Refuses at build time what the CSP would refuse at runtime, so the feedback arrives in the loop:
24	 * inline scripts, inline event handlers, javascript: URLs, and an index.html that skips the harness entry.
25	 */
26	function harnessGuard() {
27	  return {
28	    name: 'harness-guard',
29	    enforce: 'pre',
30	    transformIndexHtml: {
31	      order: 'pre',
