import { chromium } from '@playwright/test';

const BASE = 'http://127.0.0.1:4275';
const browser = await chromium.launch();
const page = await browser.newPage();
const logs = [];
page.on('console', (msg) => logs.push(`[console:${msg.type()}] ${msg.text()}`));
page.on('pageerror', (err) => logs.push(`[pageerror] ${err.message}`));

await page.goto(BASE + '/');
await page.waitForSelector('#feed .note');

const articles = await page.$$eval('#feed .note', (els) =>
  els.map((el) => ({
    id: el.getAttribute('data-note-id'),
    title: el.querySelector('.note-title')?.textContent,
    bodyHtml: el.querySelector('.note-body')?.innerHTML,
    hasAvatar: !!el.querySelector('.note-avatar'),
  })),
);
console.log('SEEDED ORDER:', JSON.stringify(articles.map((a) => a.id)));
console.log('FIRST NOTE:', JSON.stringify(articles[0], null, 2));
console.log('BOLD CHECK:', await page.$$eval('#feed .note-body b, #feed .note-body strong', (els) => els.length));
console.log('LINK CHECK:', await page.$$eval('#feed .note-body a', (els) => els.map((a) => a.getAttribute('href'))));
console.log('BR CHECK:', await page.$$eval('#feed .note-body br', (els) => els.length));

// Add a note
await page.fill('#title', 'Test note <b>bold</b>');
await page.fill('#body', 'Hello <b>world</b>\nSecond line with <a href="https://example.com">a link</a>');
await page.fill('#avatar', 'https://example.com/avatar.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(200);
console.log('TITLE VALUE AFTER SUBMIT (should be empty):', JSON.stringify(await page.inputValue('#title')));
console.log('BODY VALUE AFTER SUBMIT (should be empty):', JSON.stringify(await page.inputValue('#body')));

const newArticle = await page.$$eval('#feed .note', (els) => {
  const first = els[0];
  return { id: first.getAttribute('data-note-id'), title: first.querySelector('.note-title')?.textContent, bodyHtml: first.querySelector('.note-body')?.innerHTML };
});
console.log('NEWEST NOTE (should be the new one, first in feed):', JSON.stringify(newArticle, null, 2));

// Search
await page.fill('#search', 'Douro');
await page.waitForTimeout(150);
console.log('RESULTS LINE:', JSON.stringify(await page.textContent('#results-line')));
console.log('VISIBLE COUNT for "Douro":', await page.$$eval('#feed .note', (els) => els.length));
console.log('URL AFTER SEARCH:', page.url());

// Clear search, click a note title to select it
await page.fill('#search', '');
await page.waitForTimeout(150);
const titleButtons = await page.$$('.note-title');
await titleButtons[2].click();
await page.waitForTimeout(150);
console.log('URL AFTER SELECT:', page.url());
const current = await page.$eval('.note[aria-current="true"]', (el) => el.getAttribute('data-note-id'));
console.log('SELECTED NOTE ID:', current);

// Reload with a fragment and check restoration
const reloadUrl = BASE + '/#q=port&note=3';
await page.goto(reloadUrl);
await page.waitForTimeout(150);
console.log('SEARCH INPUT AFTER RELOAD:', JSON.stringify(await page.inputValue('#search')));
console.log('RESULTS LINE AFTER RELOAD:', JSON.stringify(await page.textContent('#results-line')));
const currentAfterReload = await page.$('.note[aria-current="true"]');
console.log('HAS SELECTED AFTER RELOAD:', !!currentAfterReload);
if (currentAfterReload) console.log('SELECTED ID AFTER RELOAD:', await currentAfterReload.getAttribute('data-note-id'));
console.log('VISIBLE NOTE IDS AFTER RELOAD (filtered by q=port):', await page.$$eval('#feed .note', (els) => els.map((e) => e.getAttribute('data-note-id'))));

await page.screenshot({ path: '.manual-check.png', fullPage: true });

console.log('CONSOLE/PAGE LOGS:', JSON.stringify(logs, null, 2));

await browser.close();

